  (10092, 'DVR.MQ.2', 4, 'قياس فعالية عملية تحقيق إيرادات من البيانات', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 191 من وثيقة سدايا.', 'DVR.4.1 (3،4،5)', 192),
  (10093, 'DVR.MQ.2', 5, 'تحسين آليات تحقيق إيرادات من البيانات', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 191–192 من وثيقة سدايا.', null, 192),
  (10094, 'OD.MQ.1', 4, 'قياس فعالية خطة البيانات المفتوحة', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 194–195 من وثيقة سدايا.', 'OD.4.1', 195),
  (10095, 'OD.MQ.1', 5, 'المراجعات الدورية لخطة البيانات المفتوحة وتحسيناتها', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 195 من وثيقة سدايا.', null, 196),
  (10096, 'OD.MQ.2', 4, 'قياس تحديد مجموعات البيانات المفتوحة وترتيب أولوياتها', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 197–198 من وثيقة سدايا.', 'OD.4.1 (KPI 2)', 198),
  (10097, 'OD.MQ.2', 5, 'تحسين اختيار البيانات المفتوحة وتوثيق الأتمتة المستخدمة', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 198 من وثيقة سدايا.', null, 199),
  (10098, 'OD.MQ.3', 4, 'قياس فعالية عمليات نشر البيانات المفتوحة', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 200–201 من وثيقة سدايا.', 'OD.4.1 (KPIs: 1، 3، 4)', 201),
  (10099, 'OD.MQ.3', 5, 'تحسين ممارسات نشر البيانات المفتوحة وصيانتها', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 201 من وثيقة سدايا.', null, 202),
  (10100, 'FOI.MQ.1', 4, 'قياس تنفيذ خطة حرية المعلومات وأنشطتها', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 202–203 من وثيقة سدايا.', null, 203),
  (10101, 'FOI.MQ.1', 4, 'نتائج التدقيق الداخلي على الامتثال للوائح حرية المعلومات', 'إرشاد لإعداد الدليل: اعرض نتائج التدقيق الداخلي على الامتثال للوائح حرية المعلومات وما ترتب عليها. راجع معايير القبول في ص 203 من وثيقة سدايا.', 'FOI.3.6', 204),
  (10102, 'FOI.MQ.1', 5, 'تحسين خطة حرية المعلومات بناءً على المراجعات', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 203 من وثيقة سدايا.', null, 204),
  (10103, 'FOI.MQ.2', 4, 'قياس فعالية الاستجابة لطلبات حرية المعلومات', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 206–207 من وثيقة سدايا.', null, 207),
  (10104, 'FOI.MQ.2', 5, 'تطوير إجراءات معالجة طلبات حرية المعلومات', 'إرشاد لإعداد الدليل: أرفق الإصدارات المنقحة لإجراءات حرية المعلومات وبيّن التعديلات. راجع معايير القبول في ص 207 من وثيقة سدايا.', null, 208),
  (10105, 'FOI.MQ.2', 5, 'توثيق أداة أتمتة الاستجابة للطلبات', 'إرشاد لإعداد الدليل: عرّف بالأداة وإصدارها وبيّن كيف تعالج الطلب من تقديمه حتى إقفاله. راجع معايير القبول في ص 207 من وثيقة سدايا.', null, 208),
  (10106, 'DC.MQ.1', 4, 'قياس تنفيذ خطة تصنيف البيانات وأنشطتها', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 208–209 من وثيقة سدايا.', null, 209),
  (10107, 'DC.MQ.1', 5, 'توثيق مراجعات خطة تصنيف البيانات وتحسيناتها', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 209 من وثيقة سدايا.', null, 210),
  (10108, 'DC.MQ.2', 4, 'قياس فعالية عمليات التصنيف', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 212 من وثيقة سدايا.', 'DC.4.1', 213),
  (10109, 'DC.MQ.2', 5, 'إثبات استخدام أدوات أتمتة تصنيف البيانات', 'إرشاد لإعداد الدليل: صف الأدوات ومراحل أتمتة التصنيف وأرفق عينات تثبت تشغيلها. راجع معايير القبول في ص 212 من وثيقة سدايا.', null, 213),
  (10110, 'DC.MQ.3', 4, 'قياس فعالية آليات مراجعة التصنيف', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 213–214 من وثيقة سدايا.', null, 214),
  (10111, 'DC.MQ.3', 5, 'مراجعة إجراءات إعادة تقييم التصنيف وتحسينها', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 214 من وثيقة سدايا.', null, 215),
  (10112, 'PDP.MQ.1', 4, 'قياس تنفيذ خطة حماية البيانات الشخصية', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 216–217 من وثيقة سدايا.', null, 217),
  (10113, 'PDP.MQ.1', 5, 'توثيق مراجعة خطة حماية البيانات الشخصية وتحسينها', 'إرشاد لإعداد الدليل: بيّن ما راجعته الجهة، وما أسفرت عنه المراجعة، والتحسينات التي نُفذت. أرفق ما يثبت التغيير ونتيجته. راجع معايير القبول في ص 217 من وثيقة سدايا.', null, 218),
  (10114, 'PDP.MQ.2', 4, 'قياس فعالية ممارسات الحماية والخصوصية', 'إرشاد لإعداد الدليل: اعرض نتائج المؤشرات المعتمدة للفترة، وقارن القيم الفعلية بالمستهدفات، وأرفق بطاقات القياس وما استندت إليه النتائج. راجع معايير القبول في ص 220 من وثيقة سدايا.', null, 221),
  (10115, 'PDP.MQ.2', 4, 'نتائج التدقيق ومتابعة الامتثال لحماية البيانات الشخصية', 'إرشاد لإعداد الدليل: وثّق نتائج التدقيق الداخلي ورفعها لمسؤول حماية البيانات ومتابعة حالات عدم الامتثال. راجع معايير القبول في ص 220 من وثيقة سدايا.', 'PDP.4.4', 221),
  (10116, 'PDP.MQ.2', 5, 'نتائج المراجعات الدورية وتحسين عمليات الحماية والخصوصية', 'إرشاد لإعداد الدليل: اربط نتائج المراجعات الدورية بالتغييرات التي أجرتها الجهة على إجراءات الحماية والخصوصية. راجع معايير القبول في ص 221 من وثيقة سدايا.', null, 222),
  (10117, 'PDP.MQ.2', 5, 'إثبات الأتمتة وإدارة التغييرات في عمليات الحماية', 'إرشاد لإعداد الدليل: بيّن كيف دارت التغييرات وأرفق ما يثبت تفعيلها في الأنظمة ومسارات العمل المؤتمتة. راجع معايير القبول في ص 221 من وثيقة سدايا.', null, 222)
), questions(standard_code,domain_name,requirement_title) as (values
  ('BIA.MQ.1', 'مجال ذكاء الأعمال والتحليلات', 'هل طورت ونفذت الجهة خطة لإدارة تنظيم ولتناغم (Orchestrate) أنشطة ذكاء الأعمال والتحليلات (BIA)؟'),
  ('BIA.MQ.2', 'مجال ذكاء الأعمال والتحليلات', 'هل حددت الجهة حالات استخدام ذكاء الأعمال والتحليلات ووضعت خطة معرفة لتنفيذ حالات الاستخدام؟'),
  ('BIA.MQ.3', 'مجال ذكاء الأعمال والتحليلات', 'هل عرَّفت الجهة ونفذت ممارسات لإدارة وحوكمة عمليات ذكاء الأعمال والتحليلات؟'),
  ('BIA.MQ.4', 'مجال ذكاء الأعمال والتحليلات', 'هل نفذت الجهة الأدوات والتقنيات وطورت المهارات المناسبة لتمكين المستخدمين ودعم تنفيذ حالات استخدام ذكاء الأعمال والتحليلات؟'),
  ('DAM.MQ.1', 'النمذجة وهيكلة البيانات', 'هل طورت ونفذت الجهة خطة لتحسين قدراتها في هيكلة البيانات؟'),
  ('DAM.MQ.2', 'النمذجة وهيكلة البيانات', 'هل طورت ونفذت الجهة ممارسات لأنشطة النمذجة وهيكلة البيانات (بما في ذلك تدفقات البيانات، ونماذج البيانات، واعتبارات الحوكمة)؟'),
  ('DC.MQ.1', 'مجال تصنيف البيانات', 'هل قامت الجهة ببناء خطة لتصنيف البيانات على النحو المنصوص عليه في معايير إدارة البيانات وحماية البيانات الشخصية؟'),
  ('DC.MQ.2', 'مجال تصنيف البيانات', 'هل الجهة عرفت، وحددت ونفذت العمليات المطلوبة لتصنيف البيانات؟'),
  ('DC.MQ.3', 'مجال تصنيف البيانات', 'هل راجعت الجهة كل مجموعات البيانات والسجلات المصنفة لضمان أن درجات التصنيف الممنوحة لها هي الأنسب وفقًا لسياسات تصنيف البيانات؟'),
  ('DCM.MQ.1', 'مجال إدارة الوثائق والمحتوى (DCM)', 'هل طورت الجهة خطة إدارة الوثائق والمحتوى (DCM) وخطة الرقمنة لإدارة تنفيذ أنشطة الإدارة غير الورقية؟'),
  ('DCM.MQ.2', 'مجال إدارة الوثائق والمحتوى (DCM)', '• هل قامت الجهة بتنفيذ سياسات وعمليات لإدارة المحتوى والوثائق وتشمل: النسخ الاحتياطي والاستعادة، والاستبقاء والحذف، والموافقة على إتاحة الوصول إلى الوثائق والمحتوى، ونشر البيانات الوصفية؟'),
  ('DCM.MQ.3', 'مجال إدارة الوثائق والمحتوى (DCM)', '• هل قامت الجهة بتنفيذ / تطبيق أداة لدعم عمليات إدارة المحتوى والوثائق وتشمل تطبيق إدارة الرقمنة؟'),
  ('DG.MQ.1', 'حوكمة البيانات', 'هل قامت الجهة ببناء وتنفيذ استراتيجية لإدارة البيانات وحماية البيانات الشخصية وخطة لإدارة البيانات وحماية البيانات الشخصية، مع وضع مؤشرات أداء رئيسية (KPIs) يمكن قياسها باستمرار لضمان التحسين؟'),
  ('DG.MQ.2', 'حوكمة البيانات', 'هل قامت الجهة بإعداد وتنفيذ السياسات والمعايير والقواعد الاسترشادية لجميع مجالات إدارة البيانات؟'),
  ('DG.MQ.3', 'حوكمة البيانات', 'هل قامت الجهة بإنشاء وتفعيل (على مستوى تنفيذ العمليات) كافة الأدوار الوظيفية المطلوبة لتنظيم إدارة البيانات وفقًا لضوابط ومواصفات مكتب إدارة البيانات الوطنية (NDMO)؟'),
  ('DG.MQ.4', 'حوكمة البيانات', 'هل قامت الجهة بوضع وتنفيذ ممارسات إدارة التغيير بما يشمل رفع مستوى الوعي، والتواصل، وضبط عملية التغيير وبناء/تطوير القدرات؟'),
  ('DO.MQ.1', 'تخزين البيانات', 'هل قامت الجهة بتطوير وتنفيذ خطة لإدارة وتلبية احتياجات تشغيل عمليات البيانات، وتخزين البيانات واستبقاء البيانات (Data Retention)؟'),
  ('DO.MQ.2', 'تخزين البيانات', 'هل لدى الجهة منهجية معرَّفة وعمليات وإجراءات تشغيلية قياسية / موحدة لعمليات قواعد البيانات؟'),
  ('DO.MQ.3', 'تخزين البيانات', 'هل لدى الجهة ممارسات وعمليات لاستمرارية الأعمال مثل الحفظ / النسخ الاحتياطي والاسترداد / التعافي من الكوارث، وهل قامت بتعريف خطة استمرارية الأعمال (BCP) للبيانات؟'),
  ('DQ.MQ.1', 'مجال جودة البيانات', 'هل طورت الجهة ونفذت خطة جودة البيانات (DQ) والتي تركز على تحسين جودة بيانات الجهة؟'),
  ('DQ.MQ.2', 'مجال جودة البيانات', 'هل وضعت / طورت الجهة ونفذت ممارسات لإدارة وتحسين جودة بيانات الجهة؟'),
  ('DQ.MQ.3', 'مجال جودة البيانات', 'هل وضعت الجهة ونفذت ممارسات لمراقبة / رصد حالة جودة بياناتها وإعداد تقاريرها؟'),
  ('DQ.MQ.4', 'مجال جودة البيانات', 'هل طورت الجهة معايير لجودة البيانات، وقدمت تعريفات لمجموعات البيانات الخاصة بها، وقامت بنشر / رفع التعريفات على فهرس البيانات الوطني (National Data Catalog (NDC))؟'),
  ('DSI.MQ.1', 'مجال تكامل البيانات ومشاركتها', 'هل طورت الجهة ونفذت خطة لتكامل البيانات ومشاركتها بما يتناسب مع سياسات مشاركة البيانات؟'),
  ('DSI.MQ.2', 'مجال تكامل البيانات ومشاركتها', 'هل عرفت الجهة ونفذت عمليات مشاركة البيانات داخل الجهة ومع الجهات الأخرى؟'),
  ('DSI.MQ.3', 'مجال تكامل البيانات ومشاركتها', 'هل عَرَّفت الجهة ونفذت هيكلة تكامل البيانات لإدارة حركة البيانات بكفاءة عبر مخازن البيانات والنظم والتطبيقات؟'),
  ('DSI.MQ.4', 'مجال تكامل البيانات ومشاركتها', 'هل طورت الجهة ونفذت ضوابط وعمليات لمشاركة البيانات من أجل تحويل البيانات وتحركها / نقلها بكفاءة؟'),
  ('DVR.MQ.1', 'مجال تحقيق القيمة من البيانات', 'هل طورت الجهة خطة لتحديد وتوثيق وتحقيق إمكانيات تحقيق إيرادات من البيانات وتنفيذ مبادرات تحسين التكلفة المتعلقة بالبيانات وحالات الاستخدام؟'),
  ('DVR.MQ.2', 'مجال تحقيق القيمة من البيانات', 'هل نفذت الجهة ممارسات لدعم عملية تحقيق إيرادات من البيانات؟'),
  ('FOI.MQ.1', 'حرية المعلومات', 'هل قامت الجهة بتعريف وبناء خطة للتعامل مع ترتيبات الامتثال لمتطلبات اللوائح التنظيمية لحرية المعلومات (FOI)؟'),
  ('FOI.MQ.2', 'حرية المعلومات', 'هل قامت الجهة بتعريف وتنفيذ العمليات المطلوبة لحرية المعلومات (FOI)؟'),
  ('MCM.MQ.1', 'مجال إدارة البيانات الوصفية ودليل / فهرس البيانات', 'هل طورت الجهة ونفذت خطة لتكامل (Integrate) وإدارة البيانات الوصفية (Metadata) عبر الجهة؟'),
  ('MCM.MQ.2', 'مجال إدارة البيانات الوصفية ودليل / فهرس البيانات', 'هل نفذت الجهة أداة / حلًا لإدارة البيانات الوصفية ودليل / فهرس البيانات؟'),
  ('MCM.MQ.3', 'مجال إدارة البيانات الوصفية ودليل / فهرس البيانات', 'هل عرَّفت الجهة ونفذت العمليات الرسمية (Formal Processes)
من أجل إدارة فعالة للبيانات الوصفية، مثل: تحديد الأولويات، والتعبئة، وإدارة إتاحة الوصول، إدارة مشاكل الجودة، إلخ.، مدعومة ومعززة بالتعاون عبر الجهة؟'),
  ('OD.MQ.1', 'البيانات المفتوحة', 'هل عرَّفت الجهة ووضعت ونفذت خطة لتحديد مجموعات بياناتها المفتوحة، وتنسيق عملية نشرها؟'),
  ('OD.MQ.2', 'البيانات المفتوحة', 'هل عرَّفت الجهة ووضعت ونفذت عملية لدعم تحديد البيانات المفتوحة؟'),
  ('OD.MQ.3', 'البيانات المفتوحة', 'هل عرَّفت الجهة ووضعت ونفذت عملية لدعم نشر مجموعات البيانات المفتوحة الخاصة بها؟'),
  ('PDP.MQ.1', 'حماية البيانات الشخصية', 'هل قامت الجهة بإجراء تقييم مبدئي لحماية البيانات الشخصية (PDP) وطورت خطة للتعامل مع المتطلبات الاستراتيجية والتشغيلية للخصوصية (لحماية خصوصية البيانات)؟'),
  ('PDP.MQ.2', 'حماية البيانات الشخصية', 'هل قامت الجهة بوضع وتنفيذ سياسات وعمليات الخصوصية للبيانات الشخصية بما في ذلك التعامل مع تسريب البيانات وإدارة الموافقات / إفادات القبول (Consents) وحقوق صاحب البيانات وتقييمات مخاطر الخصوصية؟'),
  ('RMD.MQ.1', 'مجال إدارة البيانات المرجعية والرئيسية (RMD)', 'هل قامت الجهة ببناء وتنفيذ خطة تركز على تحسين قدراتها في إدارة البيانات المرجعية والرئيسية؟'),
  ('RMD.MQ.2', 'مجال إدارة البيانات المرجعية والرئيسية (RMD)', 'هل الجهة عرَّفت ونفذت عمليات لإدارة كائنات مجموعات / أشياء (RMD Objects) البيانات المرجعية والرئيسية من الإنشاء وحتى الأرشفة؟'),
  ('RMD.MQ.3', 'مجال إدارة البيانات المرجعية والرئيسية (RMD)', 'هل قامت الجهة ببناء مركز بيانات (Data Hub) (أو أداة) كمصدر بيانات موثوق لدعم عمليات إدارة البيانات المرجعية والرئيسية؟')
)
insert into public.nudee_requirements(source_row,standard_code,domain_name,requirement_title,maturity_level,
  evidence_name,evidence_description,specification_code,acceptance_pdf_page)
select c.source_key,q.standard_code,q.domain_name,q.requirement_title,
  case c.rank when 4 then 'المستوى 4: التمكن' when 5 then 'المستوى 5: الريادة' end,
  c.title,c.guidance,c.specification,c.pdf_page
from catalog c join questions q on q.standard_code=c.question order by c.source_key;
do $$
begin
  if (select count(*) from public.nudee_requirements where source_row between 10001 and 10117 and acceptance_pdf_page is not null)<>117
     or (select count(distinct (standard_code,maturity_level)) from public.nudee_requirements where source_row between 10001 and 10117)<>84 then
    raise exception 'Expected both upper levels for all 42 published questions';
  end if;
end;
$$;

