update public.nudee_requirements r set acceptance_pdf_page=w.pdf_page
from workbook w where r.source_row=w.source_row and md5(r.standard_code||'|'||r.evidence_name)=w.signature;

create function private.nudee_maturity_levels() returns text[] language sql immutable security invoker set search_path='' as $$
 select array['المستوى 0: غياب القدرات','المستوى 1: البناء','المستوى 2: التعريف','المستوى 3: التفعيل','المستوى 4: التمكن','المستوى 5: الريادة'];
$$;
revoke all on function private.nudee_maturity_levels() from public,anon;
grant execute on function private.nudee_maturity_levels() to authenticated;

create or replace function private.nudee_question_decide(p_domain text,p_code text,p_level text,p_confirm boolean,p_previous bigint)
returns bigint language plpgsql security definer set search_path='' as $$
declare
  levels constant text[] := private.nudee_maturity_levels();
  prior bigint;
  evidence bigint[];
  result_id bigint;
begin
  if auth.uid() is null or not public.nudee_is_office() then raise exception 'Office role required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtext(p_domain),hashtext(p_code));
  select id into prior from public.nudee_question_decisions where domain_name=p_domain and standard_code=p_code order by id desc limit 1;
  if prior is distinct from p_previous then raise exception 'Question changed' using errcode='40001'; end if;
  if p_confirm is null or array_position(levels,p_level) is null or (p_level<>levels[1] and not exists (
    select 1 from public.nudee_requirements where domain_name=p_domain and standard_code=p_code and maturity_level=p_level
  )) or (p_level=levels[1] and p_confirm) or exists (select 1 from public.nudee_requirements where domain_name=p_domain and standard_code=p_code and array_position(levels,maturity_level) is null)
  or (select count(distinct requirement_title) from public.nudee_requirements where domain_name=p_domain and standard_code=p_code) <> 1
  then raise exception 'Unknown question or maturity level'; end if;
  if p_confirm then
    if (select count(distinct r.maturity_level) from public.nudee_requirements r
      where r.domain_name=p_domain and r.standard_code=p_code
      and array_position(levels,r.maturity_level) between 2 and array_position(levels,p_level))<>array_position(levels,p_level)-1
    then raise exception 'Lower evidence catalog incomplete' using errcode='23514'; end if;
    select array_agg(s.id order by r.id) into evidence
    from public.nudee_requirements r
    left join public.nudee_assignments a on a.requirement_id=r.id and a.status='approved'
    left join lateral (select id from public.nudee_submissions where assignment_id=a.id order by id desc limit 1) s on true
    where r.domain_name=p_domain and r.standard_code=p_code and array_position(levels,r.maturity_level)<=array_position(levels,p_level);
    if evidence is null or array_position(evidence,null) is not null then raise exception 'Evidence incomplete' using errcode='23514'; end if;
  end if;
  insert into public.nudee_question_decisions(domain_name,standard_code,target_level,confirmed,evidence_ids,actor_id)
    values(p_domain,p_code,p_level,p_confirm,coalesce(evidence,'{}'),auth.uid()) returning id into result_id;
  return result_id;
end;
$$;

create or replace function public.nudee_question_overview()
returns table(domain_name text,standard_code text,target_level text,question_state text,missing_count bigint)
language sql stable security invoker set search_path='' as $$
 with levels as (select private.nudee_maturity_levels() as names),
 latest as (
   select distinct on (d.domain_name,d.standard_code) d.* from public.nudee_question_decisions d
   order by d.domain_name,d.standard_code,d.id desc
 ), evidence as (
   select r.id,r.domain_name,r.standard_code,r.requirement_title,d.target_level,d.confirmed,d.evidence_ids,s.id as submission_id,
     array_position(l.names,r.maturity_level) as rank,array_position(l.names,d.target_level) as target_rank
   from public.nudee_requirements r cross join levels l
   left join latest d using(domain_name,standard_code)
   left join public.nudee_assignments a on a.requirement_id=r.id and a.status='approved'
   left join lateral (select f.id from public.nudee_submissions f where f.assignment_id=a.id order by f.id desc limit 1) s on true
   where (select public.nudee_is_office())
 ), grouped as (
   select e.domain_name,e.standard_code,e.target_level,e.confirmed,e.evidence_ids,
     bool_and(e.rank is not null) and count(distinct e.requirement_title)=1 as supported,
     count(distinct e.rank) filter(where e.rank between 2 and e.target_rank)=max(e.target_rank)-1 as levels_present,
     count(*) filter(where e.rank=e.target_rank) as at_target,
     count(*) filter(where e.rank<=e.target_rank and e.submission_id is null) as missing,
     array_agg(e.submission_id order by e.id) filter(where e.rank<=e.target_rank) as ids
   from evidence e group by e.domain_name,e.standard_code,e.target_level,e.confirmed,e.evidence_ids
 )
 select g.domain_name,g.standard_code,g.target_level,
   case when not g.supported then 'unsupported' when g.target_level is null then 'no_target'
     when g.target_level=(private.nudee_maturity_levels())[1] then 'baseline'
     when g.at_target=0 or not g.levels_present then 'unsupported' when g.missing>0 then 'blocked'
     when g.confirmed and g.evidence_ids=g.ids then 'confirmed' else 'ready' end,
   g.missing from grouped g order by g.domain_name,g.standard_code;
$$;
notify pgrst,'reload schema';
